MATHJAX = """<script>
window.MathJax={tex:{inlineMath:[['\\\\(','\\\\)']],displayMath:[['\\\\[','\\\\]']],tags:'none'}};
</script>
<script async src="https://cdn.jsdelivr.net/npm/mathjax@3/es5/tex-mml-chtml.js"></script>"""


def _esc(s: str) -> str:
    return _html.escape(s or "", quote=False)


def render_block(b: Block, *, lang: str, marker: bool = True) -> str:
    """渲染单个块。lang='en' 用 en 字段，'zh' 用 zh 字段。"""
    text = (b.en if lang == "en" else b.zh) or ""
    attr = f' data-b="{b.id}"' if marker else ""
    t = b.type

    if t in ("h1", "h2", "h3", "h4"):
        tag = {"h1": "h1", "h2": "h2", "h3": "h3", "h4": "h4"}[t]
        cls = ' class="sec"' if t == "h2" else (' class="sub"' if t == "h3" else "")
        return f"<{tag}{cls}{attr}>{_esc(text)}</{tag}>"
    if t == "abstract":
        return f'<div class="abstract"{attr}>{_esc(text)}</div>'
    if t == "figure":
        src = b.payload.get("src", "")
        cap = b.payload.get("caption", "") or text
        img = f'<img src="{_esc(src)}" alt="">' if src else ""
        cap_html = f"<figcaption>{_esc(cap)}</figcaption>" if cap else ""
        return f"<figure{attr}>{img}{cap_html}</figure>"
    if t == "table":
        cap = b.payload.get("caption", "")
        cap_html = f"<caption>{_esc(cap)}</caption>" if cap else ""
        rows = b.payload.get("rows") or []
        body = []
        for i, row in enumerate(rows):
            cell = "th" if i == 0 else "td"
            body.append("<tr>" + "".join(f"<{cell}>{_esc(c)}</{cell}>" for c in row) + "</tr>")
        return f'<table class="datatable"{attr}>{cap_html}{"".join(body)}</table>'
    if t == "eq":
        latex = b.payload.get("latex", "") or text
        num = b.payload.get("number")
        tag = f" \\tag{{{num}}}" if num else ""
        return f'<div class="eq"{attr}>\\[ {_esc(latex)}{tag} \\]</div>'
    return f"<p{attr}>{_esc(text)}</p>"


def render_fragment(blocks: list[Block], *, lang: str, marker: bool = True) -> str:
    return "\n".join(render_block(b, lang=lang, marker=marker) for b in blocks)


def document_html(
    blocks: list[Block],
    *,
    lang: str,
    title: str = "",
    subtitle: str = "",
    meta_line: str = "",
    marker: bool = True,
    lang_attr: str = "en",
) -> str:
    """合成单文件仿期刊 HTML（单栏流式，决策⑥）。"""
    mast = ""
    if title or subtitle or meta_line:
        mast = (
            '<div class="masthead">'
            + (f"<h1>{_esc(title)}</h1>" if title else "")
            + (f'<div class="title-en">{_esc(subtitle)}</div>' if subtitle else "")
            + (f'<div class="meta">{_esc(meta_line)}</div>' if meta_line else "")
            + "</div>"
        )
    return f"""<!DOCTYPE html>
<html lang="{lang_attr}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{_esc(title or 'papershelf')}</title>
{MATHJAX}
<style>{CSS}</style>
</head>
<body>
<div class="page">
{mast}
{render_fragment(blocks, lang=lang, marker=marker)}
</div>
</body>
</html>
"""


def en_html(doc: Doc, *, marker: bool = True) -> str:
    meta = doc.meta
    return document_html(
        doc.blocks,
        lang="en",
        title=meta.get("title_en", ""),
        subtitle=meta.get("title_zh", ""),
        meta_line=meta.get("authors", ""),
        marker=marker,
        lang_attr="en",
    )
