{"content": """"合成导出 HTML —— 决策⑳ 的派生轨道（JSON → 单文件 HTML）。

阅读器用块级 JSON 渲染；**导出/分享**时才由本模块合成自包含 HTML。
`dual` 模式输出左右并排对照（决策⑤），用 CSS grid 让同 ID 的中英块天然对齐。
"""

from __future__ import annotations

from .markup import CSS, MATHJAX, _esc, render_block
from .model import Block

DUAL_CSS = """
.dual{display:grid;grid-template-columns:1fr 1fr;gap:0 26px;align-items:start}
.dual .col{min-width:0}
@media(max-width:900px){.dual{grid-template-columns:1fr}.dual .col.zh{margin-top:10px}}
.dual .row{display:contents}
.dual .zh{border-left:2px solid var(--rule);padding-left:16px}
"""


def _shell(title: str, lang_attr: str, body: str, extra_css: str = "") -> str:
    return f"""<!DOCTYPE html>
<html lang="{lang_attr}">
<head>
<meta charset="UTF-8">
<meta name="viewport" content="width=device-width, initial-scale=1.0">
<title>{_esc(title or 'papershelf')}</title>
{MATHJAX}
<style>{CSS}{extra_css}</style>
</head>
<body>
<div class="page">
{body}
</div>
</body>
</html>
"""


def synth_dual(blocks: list[Block], *, title: str = "", meta_line: str = "") -> str:
    """中英左右并排（导出/分享形态）。同一块 ID 左右相邻，天然对齐。"""
    rows = []
    for b in blocks:
        rows.append(f'<div class="row">{render_block(b, lang="en")}{render_block(b, lang="zh")}</div>')
    head = (
        f'<div class="masthead"><h1>{_esc(title)}</h1>'
        + (f'<div class="meta">{_esc(meta_line)}</div>' if meta_line else "")
        + "</div>"
    )
    body = f'{head}<div class="dual">{chr(10).join(rows)}</div>'
    return _shell(title, "zh-CN", body, extra_css=DUAL_CSS)


def synth_single(blocks: list[Block], *, lang: str, title: str = "", meta_line: str = "") -> str:
    head = (
        f'<div class="masthead"><h1>{_esc(title)}</h1>'
        + (f'<div class="meta">{_esc(meta_line)}</div>' if meta_line else "")
        + "</div>"
    )
    body = head + "\n".join(render_block(b, lang=lang) for b in blocks)
    return _shell(title, "en" if lang == "en" else "zh-CN", body)


def synth(blocks: list[Block], mode: str, *, title: str = "", meta_line: str = "") -> str:
    if mode == "dual":
        return synth_dual(blocks, title=title, meta_line=meta_line)
    return synth_single(blocks, lang=mode, title=title, meta_line=meta_line)
