{"content": """"认证路由（决策⑭⑮㉑）：注册 / 激活 / 登录 / 登出 / 当前用户。

⑮ 的降级逻辑就在这里：**SMTP 配全 → 开放自助注册；未配 → 注册口关闭（403）**，
改由管理员在 `/api/admin/users` 开号。
"""

from __future__ import annotations

import sqlite3
from typing import Any

from fastapi import APIRouter, Depends, HTTPException, Response, status
from pydantic import BaseModel, Field

from ..config import Settings, get_settings
from ..db import new_token, rows_to_list, tx, utcnow
from ..mailer import send_activation
from ..security import (
    SESSION_COOKIE,
    SESSION_DAYS,
    activate_user,
    create_user,
    current_user,
    email_allowed,
    end_session,
    get_conn,
    start_session,
    user_by_email,
    verify_password,
)

router = APIRouter(prefix="/api/auth", tags=["auth"])


class RegisterIn(BaseModel):
    email: str
    password: str = Field(min_length=8, max_length=200)
    display_name: str = ""


class LoginIn(BaseModel):
    email: str
    password: str


def _public_user(u: dict[str, Any]) -> dict[str, Any]:
    return {"id": u["id"], "email": u["email"], "display_name": u["display_name"],
            "is_admin": bool(u["is_admin"]), "status": u["status"]}


@router.get("/config")
def auth_config(settings: Settings = Depends(get_settings)) -> dict[str, Any]:
    """前端据此决定「显示注册表单」还是「提示联系管理员开号」（⑮）。"""
    return {
        "open_registration": settings.open_registration,
        "smtp_configured": settings.smtp_configured,
        "allowed_domains": settings.allowed_domains,
    }


@router.post("/register")
def register(
    body: RegisterIn,
    conn: sqlite3.Connection = Depends(get_conn),
    settings: Settings = Depends(get_settings),
) -> dict[str, Any]:
    # ⑮：未配 SMTP → 自助注册自动关闭，改由管理员开号
    if not settings.open_registration:
        raise HTTPException(
            status.HTTP_403_FORBIDDEN,
            "本站未配置邮件服务，自助注册已关闭，请联系管理员开通账号",
        )
    # ⑭：限白名单域名（默认 *.edu.cn）
    if not email_allowed(body.email, settings):
        raise HTTPException(
            status.HTTP_400_BAD_REQUEST,
            f"仅接受以下域名的邮箱：{', '.join(settings.allowed_domains) or '（未限制）'}",
        )
    if user_by_email(conn, body.email):
        raise HTTPException(status.HTTP_409_CONFLICT, "该邮箱已注册")

    user_id = create_user(conn, email=body.email, password=body.password,
                          display_name=body.display_name, status_="pending")
    token = new_token(24)
    with tx(conn):
        conn.execute(
            "INSERT INTO activation_tokens (token, user_id, created_at) VALUES (?,?,?)",
            (token, user_id, utcnow()),
        )
    link = f"{settings.base_url}/activate?token={token}"
    sent = send_activation(settings, body.email, link)
    return {"state": "pending", "email_sent": sent, "activate_url": None if sent else link}


@router.get("/activate")
def activate(token: str, conn: sqlite3.Connection = Depends(get_conn)) -> dict[str, Any]:
    row = conn.execute("SELECT * FROM activation_tokens WHERE token=?", (token,)).fetchone()
    if row is None:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "激活链接无效或已使用")
    activate_user(conn, int(row["user_id"]))
    with tx(conn):
        conn.execute("DELETE FROM activation_tokens WHERE token=?", (token,))
    return {"state": "active"}


@router.post("/login")
def login(
    body: LoginIn,
    response: Response,
    conn: sqlite3.Connection = Depends(get_conn),
) -> dict[str, Any]:
    user = user_by_email(conn, body.email)
    if user is None or not verify_password(user["password_hash"], body.password):
        raise HTTPException(status.HTTP_401_UNAUTHORIZED, "邮箱或密码不正确")
    if user["status"] == "disabled":
        raise HTTPException(status.HTTP_403_FORBIDDEN, "账号已被禁用")
    if user["status"] == "pending":
        raise HTTPException(status.HTTP_403_FORBIDDEN, "账号尚未激活，请查收激活邮件")
    token, _ = start_session(conn, int(user["id"]))
    response.set_cookie(
        SESSION_COOKIE, token, httponly=True, samesite="lax", max_age=SESSION_DAYS * 86400,
    )
    return _public_user(user)


@router.post("/logout")
def logout(response: Response, conn: sqlite3.Connection = Depends(get_conn),
           token: str | None = None) -> dict[str, bool]:
    if token:
        end_session(conn, token)
    response.delete_cookie(SESSION_COOKIE)
    return {"ok": True}


@router.get("/me")
def me(user: dict[str, Any] = Depends(current_user)) -> dict[str, Any]:
    return _public_user(user)
