{"content": "/** 登录页 —— ⑭⑮ 的服务端策略直接体现在这里：
 *  未配 SMTP → 不显示注册入口，改为提示「联系管理员开号」；
 *  配了 SMTP → 显示注册表单，并明示只接受白名单域名。 */

import { useEffect, useState } from 'react'
import { Link, useNavigate, useSearchParams } from 'react-router-dom'

import { api } from '../api'
import { useAuth } from '../auth'
import type { AuthConfig } from '../types'

export function LoginPage() {
  const { login, user } = useAuth()
  const nav = useNavigate()
  const [params] = useSearchParams()
  const [email, setEmail] = useState('')
  const [password, setPassword] = useState('')
  const [cfg, setCfg] = useState<AuthConfig | null>(null)
  const [error, setError] = useState('')
  const [busy, setBusy] = useState(false)

  useEffect(() => { api.authConfig().then(setCfg).catch(() => setCfg(null)) }, [])
  useEffect(() => { if (user) nav('/plans', { replace: true }) }, [user, nav])

  const activated = params.get('activated')
  const activateError = params.get('activate_error')

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setBusy(true); setError('')
    try {
      await login(email, password)
      nav(params.get('next') || '/plans', { replace: true })
    } catch (err) {
      setError(err instanceof Error ? err.message : '登录失败')
    } finally { setBusy(false) }
  }

  return (
    <div className="page" style={{ maxWidth: 460 }}>
      <h1>papershelf</h1>
      <p className="muted">PDF / arXiv → 保版式中文精读</p>

      {activated && <div className="banner ok">邮箱已验证，请登录。</div>}
      {activateError && <div className="banner error">激活链接无效或已使用，请重新申请。</div>}
      {error && <div className="banner error">{error}</div>}

      <form className="card stack" onSubmit={submit}>
        <div className="field" style={{ maxWidth: '100%' }}>
          <label>邮箱</label>
          <input value={email} onChange={(e) => setEmail(e.target.value)} type="email"
                 autoComplete="username" required />
        </div>
        <div className="field" style={{ maxWidth: '100%' }}>
          <label>密码</label>
          <input value={password} onChange={(e) => setPassword(e.target.value)} type="password"
                 autoComplete="current-password" required />
        </div>
