import { useEffect, useState } from 'react'
import { Link, useNavigate } from 'react-router-dom'

import { ApiError, api } from '../api'
import type { AuthConfig } from '../types'

export function RegisterPage() {
  const nav = useNavigate()
  const [cfg, setCfg] = useState<AuthConfig | null>(null)
  const [email, setEmail] = useState('')
  const [name, setName] = useState('')
  const [password, setPassword] = useState('')
  const [error, setError] = useState('')
  const [link, setLink] = useState('')
  const [busy, setBusy] = useState(false)

  useEffect(() => { api.authConfig().then(setCfg).catch(() => setCfg(null)) }, [])

  async function submit(e: React.FormEvent) {
    e.preventDefault()
    setBusy(true); setError(''); setLink('')
    try {
      const r = await api.register(email, password, name)
      if (r.email_sent) nav('/login?registered=1', { replace: true })
      else setLink(r.activate_url || '')
    } catch (err) {
      setError(err instanceof ApiError ? err.message : '注册失败')
    } finally { setBusy(false) }
  }

  if (cfg && !cfg.open_registration) {
    return (
      <div className="page" style={{ maxWidth: 460 }}>
        <h1>注册已关闭</h1>
        <p className="muted">本站未配置邮件服务，无法自助注册。请联系管理员开通账号。</p>
        <Link className="btn" to="/login">返回登录</Link>
      </div>
    )
  }

  return (
    <div className="page" style={{ maxWidth: 460 }}>
      <h1>注册</h1>
      {cfg && cfg.allowed_domains.length > 0 && (
        <p className="muted">仅接受以下域名的邮箱：{cfg.allowed_domains.join('、')}</p>
      )}
      {error && <div className="banner error">{error}</div>}
      {link && (
        <div className="banner ok">
          邮件发送失败，请直接打开下面的链接完成激活：
          <div style={{ marginTop: 6, wordBreak: 'break-all' }}>
            <a href={link}>{link}</a>
          </div>
        </div>
      )}
      <form className="card stack" onSubmit={submit}>
        <div className="field" style={{ maxWidth: '100%' }}>
          <label>邮箱</label>
          <input value={email} onChange={(e) => setEmail(e.target.value)} type="email" required />
        </div>
        <div className="field" style={{ maxWidth: '100%' }}>
          <label>姓名（可选）</label>
          <input value={name} onChange={(e) => setName(e.target.value)} />
        </div>
        <div className="field" style={{ maxWidth: '100%' }}>
          <label>密码（至少 8 位）</label>
          <input value={password} onChange={(e) => setPassword(e.target.value)} type="password"
                 minLength={8} required />
        </div>
        <button className="primary" disabled={busy}>{busy ? '提交中…' : '注册并发送激活邮件'}</button>
      </form>
      <p className="muted" style={{ marginTop: 12 }}>
        已有账号？<Link to="/login">登录</Link>
      </p>
    </div>
  )
}
