{"content": "/** 精读阅读器 —— 决策⑤⑥⑯⑰⑳ 汇聚的地方。
 *
 * 核心机制（改动前务必理解）：
 * 1. **配对由块 ID 保证**：中英两列渲染的是同一份块数组，同一行共享 `id`，
 *    所以左右天然对齐，不需要任何"段落对齐"算法（决策④ 的构造性保证）。
 * 2. **免中文块单栏横跨**（`no_zh`）：参考文献、纯公式、尚无译文 → 只渲染英文一次。
 *    否则同一条公式会在左右各出现一遍，既冗余又误导。
 * 3. **公式是服务端渲染的 MathML**（`en_html`/`zh_html` 来自后端，遗留项 8）：
 *    前端零数学运行时。这里用 `dangerouslySetInnerHTML` 是**有意为之**——
 *    内容是本服务端自己渲染的块 HTML（不是用户贴的 HTML），且服务端已做转义。
 * 4. **滚动进度上报**：合并 scroll 事件，只在百分比变化 ≥1 时上报（决策⑰ 的"滚动自动"）。
 *    已标记「已读」时后端会 409 拒绝——前端捕获后静默，因为那是预期的锁定行为。
 */

import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { Link, useNavigate, useParams } from 'react-router-dom'

import { ApiError, api } from '../api'
import type { Block, Note, PaperDoc } from '../types'

const DEFAULTS = { dark: false }

function blockText(b: Block, lang: 'en' | 'zh') {
  return lang === 'en' ? b.en : (b.zh || b.en)
}

/** 块渲染：服务端给 HTML 就直接用，没有则退化为纯文本（不丢内容）。 */
function BlockBody({ block, lang }: { block: Block; lang: 'en' | 'zh' }) {
  const html = lang === 'en' ? block.en_html : block.zh_html
  if (!html) return <div>{blockText(block, lang)}</div>
  return <div dangerouslySetInnerHTML={{ __html: html }} />
}

export function ReaderPage() {
  const { paperId = '' } = useParams()
  const pid = Number(paperId)
  const nav = useNavigate()

  const [doc, setDoc] = useState<PaperDoc | null>(null)
  const [error, setError] = useState('')
  const [notes, setNotes] = useState<Note[]>([])
  const [focus, setFocus] = useState<string>('')
  const [editing, setEditing] = useState<{ id: string; text: string } | null>(null)
  const [onlyZh, setOnlyZh] = useState(false)
  const [showTools, setShowTools] = useState(true)
  const [noteOpen, setNoteOpen] = useState(false)
  const [refreshing, setRefreshing] = useState(false)

  const scrollRef = useRef<HTMLDivElement>(null)
  const lastPct = useRef(-1)

  const load = useCallback(async () => {
    try {
      const d = await api.doc(pid)
      setDoc(d)
      setError('')
      try { setNotes(await api.notes(pid)) } catch { /* 笔记失败不该拦住阅读 */ }
    } catch (e) {
      setError(e instanceof ApiError && e.status === 409
        ? '这篇文献还在转换中，稍后自动刷新…'
        : (e instanceof Error ? e.message : '加载失败'))
    }
  }, [pid])

  useEffect(() => { if (Number.isFinite(pid)) void load() }, [pid, load])

  // 未就绪时轮询（② 全自动无人值守，用户不必手动刷新）
  useEffect(() => {
    if (doc || error === '') return
    const t = window.setInterval(() => { void load() }, 4000)
    return () => window.clearInterval(t)
  }, [doc, error, load])

  // ── ⑰ 滚动进度自动上报（节流 + 只在变化 ≥1% 时发）──
  const onScroll = useCallback(() => {
    const el = scrollRef.current
    if (!el) return
    const max = el.scrollHeight - el.clientHeight
    if (max <= 0) return
    const pct = Math.min(100, Math.round((el.scrollTop / max) * 100))
    if (pct <= lastPct.current) return
    if (pct - lastPct.current < 2 && pct < 100) return
    lastPct.current = pct
    api.updatePaper(pid, { progress: pct } as never).catch((e) => {
      // 409 = 已标记已读、进度锁定（预期行为，不打扰用户）
      if (!(e instanceof ApiError) || e.status !== 409) console.warn(e)
    })
  }, [pid])

  const ordered = doc?.blocks ?? []
  const focusIdx = useMemo(() => ordered.findIndex((b) => b.id === focus), [ordered, focus])

  async function saveBlock() {
    if (!editing) return
    const { id, text } = editing
    try {
      await api.editBlock(pid, id, text, true)
      setDoc((d) => d && ({
        ...d,
        blocks: d.blocks.map((b) => b.id === id
          ? { ...b, zh: text, zh_source: 'human', needs_review: false } : b),
      }))
      setEditing(null)
    } catch (e) { alert(e instanceof Error ? e.message : '保存失败') }
  }

  async function retranslate(b: Block) {
    try {
      const r = await api.retranslateBlock(pid, b.id)
      setDoc((d) => d && ({
        ...d,
        blocks: d.blocks.map((x) => x.id === b.id
          ? { ...x, zh: r.zh, zh_source: 'mt', needs_review: false } : x),
      }))
    } catch (e) { alert(e instanceof Error ? e.message : '重译失败') }
  }

  async function refreshDoc() {
    setRefreshing(true)
    try {
      const d = await api.doc(pid)
      setDoc(d)
    } finally { setRefreshing(false) }
  }

  if (error) {
    return (
      <div className="page">
        <p className="muted"><Link to="/plans">← 计划</Link></p>
        <div className="banner error">{error}</div>
        <button onClick={() => void load()}>重试</button>
      </div>
    )
  }
  if (!doc) return <div className="page"><p className="muted">加载中…</p></div>

  return (
    <div className="reader">
      <div className="reader-bar">
        <button className="ghost" onClick={() => nav(-1)}>←</button>
        <strong style={{ maxWidth: '34%', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>
          {doc.meta.title_zh || doc.meta.title_en || `文献 #${pid}`}
        </strong>
        <div className="spacer" />
        <button className="ghost" onClick={() => { setOnlyZh((v) => !v) }}>
          {onlyZh ? '显示对照' : '只看中文'}
        </button>
        <button className="ghost" onClick={() => setShowTools((v) => !v)}>
          {showTools ? '隐藏块工具' : '显示块工具'}
        </button>
        <button className="ghost" onClick={() => void refreshDoc()} disabled={refreshing}>
          {refreshing ? '刷新中…' : '刷新'}
        </button>
        <button className="ghost" onClick={() => setNoteOpen((v) => !v)}>
          笔记（{notes.length}）
        </button>
        <a className="btn" href={api.exportUrl(pid, 'dual')} target="_blank" rel="noreferrer">导出对照</a>
        <a className="btn" href={api.exportUrl(pid, 'zh')} target="_blank" rel="noreferrer">导出中文</a>
      </div>

      <div className="reader-body" ref={scrollRef} onScroll={onScroll}>
        <div className="reader-cols" style={{ maxWidth: onlyZh ? 880 : 1500 }}>
          {doc.blocks.map((b) => {
            const wide = b.no_zh || !(b.zh || '').trim()
            const isFocus = b.id === focus
            return (
              <div key={b.id} className={`pair${wide || onlyZh ? ' wide' : ''}${isFocus ? ' focus' : ''}`}
                   data-b={b.id}
                   onClick={() => setFocus(b.id)}>
                <div className="col en">
                  <BlockBody block={b} lang={onlyZh ? 'zh' : 'en'} />
                  {showTools && (
                    <div className="block-tools">
                      {b.zh_source === 'human' && <span className="chip ok">已人工修订</span>}
                      {b.needs_review && <span className="chip warn">待校对</span>}
                      {!b.no_zh && (
                        <>
                          <button onClick={(e) => { e.stopPropagation(); setEditing({ id: b.id, text: b.zh }) }}>
                            编辑译文
                          </button>
                          <button onClick={(e) => { e.stopPropagation(); void retranslate(b) }}>重译此块</button>
                          <button onClick={(e) => { e.stopPropagation(); setNoteOpen(true); setFocus(b.id) }}>
                            加笔记
                          </button>
                        </>
                      )}
                    </div>
                  )}
                </div>
                <div className="col zh"><BlockBody block={b} lang="zh" /></div>
              </div>
            )
          })}
        </div>
      </div>

      {editing && (
        <div className="drawer-mask" onClick={() => setEditing(null)} />
      )}
      {editing && (
        <aside className="drawer">
          <header>
            <strong style={{ flex: 1 }}>编辑译文 · {editing.id}</strong>
            <button className="ghost" onClick={() => setEditing(null)}>取消</button>
          </header>
          <div className="body stack">
            <div>
              <label>英文原文</label>
              <div style={{ fontSize: 14, background: '#faf9f6', border: '1px solid var(--rule)',
                            borderRadius: 4, padding: '8px 10px', maxHeight: 200, overflow: 'auto' }}>
                {ordered.find((x) => x.id === editing.id)?.en}
              </div>
            </div>
            <div>
              <label>中文译文（保存后标记为「人工修订」，重跑不会被覆盖）</label>
              <textarea rows={10} value={editing.text}
                        onChange={(e) => setEditing({ ...editing, text: e.target.value })} />
            </div>
            <button className="primary" onClick={() => void saveBlock()}>保存</button>
          </div>
        </aside>
      )}

      {noteOpen && (
        <aside className="drawer">
          <header>
            <strong style={{ flex: 1 }}>笔记</strong>
            <button className="ghost" onClick={() => setNoteOpen(false)}>关闭</button>
          </header>
          <div className="body">
            <NotePanel
              paperId={pid}
              notes={notes}
              focusBlock={focusIdx >= 0 ? ordered[focusIdx] : null}
              onChange={setNotes}
              onJump={(bid) => {
                setFocus(bid)
                document.querySelector(`[data-b="${bid}"]`)?.scrollIntoView({ block: 'center', behavior: 'smooth' })
              }}
            />
          </div>
        </aside>
      )}
    </div>
  )
}

function NotePanel({ paperId, notes, focusBlock, onChange, onJump }: {
  paperId: number
  notes: Note[]
  focusBlock: Block | null
  onChange: (n: Note[]) => void
  onJump: (blockId: string) => void
}) {
  const [text, setText] = useState('')
  const [anchor, setAnchor] = useState(true)

  async function add() {
    if (!text.trim()) return
    const n = await api.addNote(paperId, text.trim(), anchor && focusBlock ? focusBlock.id : null)
    onChange([n, ...notes])
    setText('')
  }
  return (
    <div className="stack">
      <div>
        <label>
          {anchor && focusBlock
            ? `锚定到当前块 ${focusBlock.id}（${blockText(focusBlock, 'zh').slice(0, 24)}…）`
            : '文献级笔记'}
        </label>
        <textarea rows={3} value={text} onChange={(e) => setText(e.target.value)}
                  placeholder="写点什么…（Ctrl/Cmd + Enter 提交）"
                  onKeyDown={(e) => { if ((e.metaKey || e.ctrlKey) && e.key === 'Enter') void add() }} />
      </div>
      <label className="row" style={{ gap: 6, marginBottom: 0 }}>
        <input type="checkbox" checked={anchor} onChange={(e) => setAnchor(e.target.checked)}
               style={{ width: 'auto' }} />
        <span>锚定到选中的块</span>
      </label>
      <button className="primary" onClick={() => void add()} disabled={!text.trim()}>添加笔记</button>

      <div className="notelist">
        {notes.map((n) => (
          <div className="note" key={n.id}>
            {n.block_id && (
              <button className="ghost" style={{ fontSize: 12, padding: 0 }}
                      onClick={() => onJump(n.block_id as string)}>
                ⌖ {n.block_id}
              </button>
            )}
            <div style={{ whiteSpace: 'pre-wrap' }}>{n.content}</div>
            <div className="row meta">
              <span>{(n.created_at || '').slice(0, 16).replace('T', ' ')}</span>
              <div className="spacer" />
              <button className="ghost" style={{ fontSize: 12, padding: 0 }}
                      onClick={() => void api.deleteNote(n.id).then(() => onChange(notes.filter((x) => x.id !== n.id)))}>
                删除
              </button>
            </div>
          </div>
        ))}
        {notes.length === 0 && <p className="muted">还没有笔记。</p>}
      </div>
    </div>
  )
}
