function blockText(b: Block, lang: 'en' | 'zh') {
  return lang === 'en' ? b.en : (b.zh || b.en)
}

/** 块渲染：服务端给 HTML 就直接用，没有则退化为纯文本（不丢内容）。 */
function BlockBody({ block, lang }: { block: Block; lang: 'en' | 'zh' }) {
  const html = lang === 'en' ? block.en_html : block.zh_html
  if (!html) return <div>{blockText(block, lang)}</div>
  return <div dangerouslySetInnerHTML={{ __html: html }} />
}

