    if not _SAFE_ASSET_NAME.match(name) or "/" in name or "\\" in name or ".." in name:
        raise HTTPException(status.HTTP_400_BAD_REQUEST, "非法文件名")
    base = (settings.papers_dir / f"p{pid}" / "assets").resolve()
