/** 计划列表 —— 原型「看板」一栏的对应物（决策⑦：计划是私有归属载体）。
 *  卡片上直接给三个必看数：篇数 / 已读 / 目标，点击进计划详情。 */

import { useCallback, useEffect, useState } from 'react'
import { Link } from 'react-router-dom'

import { api } from '../api'
import type { Plan } from '../types'

export function PlansPage() {
  const [plans, setPlans] = useState<Plan[]>([])
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState('')
  const [creating, setCreating] = useState(false)
  const [name, setName] = useState('')
  const [desc, setDesc] = useState('')
  const [goal, setGoal] = useState('')

  const load = useCallback(async () => {
    setLoading(true)
    try { setPlans(await api.plans()) } catch (e) {
      setError(e instanceof Error ? e.message : '加载失败')
    } finally { setLoading(false) }
  }, [])

  useEffect(() => { void load() }, [load])

  async function create(e: React.FormEvent) {
    e.preventDefault()
    if (!name.trim()) return
    try {
      await api.createPlan(name.trim(), desc.trim(), goal ? Number(goal) : null)
      setName(''); setDesc(''); setGoal(''); setCreating(false)
      await load()
    } catch (err) { setError(err instanceof Error ? err.message : '创建失败') }
  }

  return (
    <div className="page">
      <div className="row">
        <h1>我的计划</h1>
        <div className="spacer" />
        <button className="primary" onClick={() => setCreating((v) => !v)}>
          {creating ? '取消' : '新建计划'}
        </button>
      </div>
      <p className="muted">一个计划 = 一个研究方向或一门课；文献与术语表都挂在计划内。</p>

      {error && <div className="banner error">{error}</div>}

      {creating && (
        <form className="card stack" onSubmit={create} style={{ marginTop: 14 }}>
          <div className="field">
            <label>计划名称</label>
            <input value={name} onChange={(e) => setName(e.target.value)} placeholder="如：安全控制精读" required />
          </div>
          <div className="row wrap" style={{ alignItems: 'flex-end', gap: 14 }}>
            <div className="field" style={{ flex: '2 1 260px' }}>
              <label>说明（可选）</label>
              <input value={desc} onChange={(e) => setDesc(e.target.value)} />
            </div>
            <div className="field" style={{ flex: '0 1 140px' }}>
              <label>目标篇数（可选）</label>
              <input value={goal} onChange={(e) => setGoal(e.target.value)} type="number" min={1} />
            </div>
          </div>
          <div><button className="primary">创建</button></div>
        </form>
      )}

