    async def static_file(request: Request):
        name = request.url.path.lstrip("/")
        if name not in _STATIC_FILES:
            raise HTTPException(status.HTTP_404_NOT_FOUND, "Not Found")
        target = STATIC_DIR / name
        if not target.is_file():
            raise HTTPException(status.HTTP_404_NOT_FOUND, "Not Found")
